INSERT INTO scenarios (id, npc_name, description) VALUES
(1, 'Мартин_99', 'Добиваш порака од непознат профил кој тврди дека има смешни слики од твојот лик во играта. Профилот испраќа непознат линк и те убедува да го отвориш веднаш.'),
(2, 'GameAdmin', 'Корисник кој се претставува како администратор ти нуди бесплатни поени и бара да му ја испратиш лозинката.'),
(3, 'Училишен компјутер', 'На училишниот компјутер се појавува официјално безбедносно ажурирање кое бара рестартирање.'),
(4, 'Непознат USB', 'Под клупата наоѓаш непозната USB-меморија и треба да одлучиш како безбедно да постапиш.'),
(5, 'ShadowAce', 'Онлајн играч бара информации за твоето училиште, местото каде живееш и времето кога нема никој дома.'),
(6, 'FREE_FAST_WIFI', 'Во интернет-кафуле се појавува непозната отворена Wi-Fi мрежа преку која треба да се најавиш на е-пошта.'),
(7, 'FastExpress Delivery', 'Добиваш неочекувана порака дека пратка не може да биде доставена и линкот бара лични и платежни податоци.'),
(8, 'Account Security', 'Добиваш е-пошта дека лозинката е променета, иако не си побарал промена, а пораката бара стара лозинка.'),
(9, 'Критично предупредување', 'Во прелистувачот се појавува драматично предупредување за вируси кое бара телефонски повик и далечински пристап.'),
(10, 'Скенирај и освои', 'На социјална мрежа гледаш QR-код за наградна игра без јасен организатор, а формуларот бара лични податоци и лозинка.'),
(11, 'FreeCoins Mod', 'Соученик ти препорачува неофицијална програма за играта со непознат издавач и администраторски дозволи.'),
(12, 'Сметката на соученикот', 'Не можеш да се најавиш на училишната платформа, па соученик ти ја нуди својата сметка со лични пораки и оценки.'),
(13, 'Непознат USB-кабел', 'Во училницата наоѓаш непознат USB-кабел и соученик сака да го приклучи во училишниот лаптоп.'),
(14, 'Пронајден таблет', 'Во училницата наоѓаш отклучен таблет со видливи пораки, фотографии и е-пошта.'),
(15, 'Предизвик со ученичка картичка', 'На социјалните мрежи се шири предизвик во кој учениците објавуваат фотографии од ученички картички и локација.'),
(16, 'AlexNova', 'Онлајн познаник предлага веднаш да се сретнете во паркот, бара да дојдеш сам и никому да не кажуваш.'),
(17, 'Поглед преку рамо', 'Додека се најавуваш на е-пошта во интернет-кафуле, лице зад тебе го набљудува екранот и тастатурата.'),
(18, 'Отворена сесија', 'По користење споделен компјутер, е-поштата останува најавена, лозинката можеби е зачувана, а датотека останува во Downloads.');
